{
  "name": "Keithley 2400/2182 I-V测量系统",
  "name_en": "Keithley 2400/2182 I-V Measurement System",
  "manufacturer": "Keithley",
  "description": "由Keithley 2400源表与2182纳伏表组成的精密电学测量系统，用于向样品施加电流并测量微弱电压信号，常用于I-V扫描、电阻表征和低噪声电输运实验。",
  "description_en": "A precision electrical measurement system combining a Keithley 2400 SourceMeter and a 2182 nanovoltmeter. It is used to source current into a sample and measure very small voltage signals for I-V sweeps, resistance characterization, and low-noise transport experiments.",
  "tag_hints": [
    "I-V sweeps",
    "current sourcing",
    "nanovoltmeter",
    "SourceMeter",
    "low-noise electrical measurement",
    "resistance characterization",
    "Keithley 2400",
    "Keithley 2182"
  ],
  "actions": [
    {
      "action_name": "auto-configure_source",
      "description": "配置2400源表的电流输出量程和电压保护限值。",
      "description_en": "Configure the 2400 SourceMeter current output range and voltage compliance limit."
    },
    {
      "action_name": "auto-connect_instruments",
      "description": "连接Keithley 2400源表和2182纳伏表。",
      "description_en": "Connect to the Keithley 2400 SourceMeter and 2182 nanovoltmeter."
    },
    {
      "action_name": "auto-measure_point",
      "description": "在指定电流下进行单点测量，并对电压读数取平均。",
      "description_en": "Perform a single measurement point at the specified current and average the voltage readings."
    },
    {
      "action_name": "auto-run_sweep",
      "description": "执行电流扫描并记录I-V测量数据。",
      "description_en": "Run a current sweep and record the I-V measurement data."
    },
    {
      "action_name": "auto-shutdown",
      "description": "安全关闭源输出并停止测量仪器。",
      "description_en": "Safely turn off the source output and stop the measurement instruments."
    }
  ]
}

